"""Chapter 26 -- Earth system prediction.

A hierarchy of slow reservoirs, a forcing that is part of the state rather
than prescribed, and an emergent constraint that is measured exactly and
still tells you nothing.

Part VI of *An Interactive Chaos and Predictability Textbook*.

Numerics come from `chaoslib`; this file holds the exposition and the figures.
The experiments are precomputed by `scripts/generate_ch26_data.py`.

To edit:   marimo edit notebooks/ch26_earth-system-prediction.py
To export: make nb-one NB=ch26_earth-system-prediction
"""

import marimo

__generated_with = "0.23.9"
app = marimo.App(width="full", app_title="Chapter 26: Earth System Prediction")


@app.cell
async def imports():
    import marimo as mo

    import sys

    if sys.platform == "emscripten":
        import micropip

        await micropip.install(
            str(
                mo.notebook_location()
                / "public"
                / "chaoslib-0.1.0-py3-none-any.whl"
            )
        )
    else:
        sys.path.insert(0, str(mo.notebook_dir().parent))

    import numpy as np
    import matplotlib.pyplot as plt

    from chaoslib import errorgrowth, plotting, systems

    C_CONTEXT = plotting.mpl_colour(plotting.C_CONTEXT)
    C_TRUTH = plotting.C_TRUTH
