# ===========================================================================
# Section 1
# ===========================================================================
@app.cell(hide_code=True)
def s1_md(TIMESCALES, mo):
    mo.md(
        rf"""
    ## 1 · A hierarchy of memories

    Four reservoirs, $T_k = {', '.join(f'{t:g}' for t in TIMESCALES)}$, all integrating
    the **same** weather. Nothing distinguishes them but one number each.

    Be clear about what is and is not a measurement here. The memory is a **parameter**:
    undriven, each reservoir decays as $e^{{-t/T_k}}$ exactly, and a test asserts it to
    $10^{{-10}}$. What Hasselmann's argument actually predicts is the **amplitude** — a
    reservoir integrating white weather has

    $$
    \sigma_S = \sigma_z \sqrt{{\tau_{{\rm int}}/T}} ,
    $$

    so $\sigma_S\sqrt{{T}}$ should be the same for every reservoir. That is a claim worth
    checking, and it fails in an instructive place.
    """
    )
    return


@app.cell(hide_code=True)
def s1_fig(
    C_BG, C_TRUTH, MPL_SEQUENTIAL, RESERVOIR_SD, RESERVOIR_SD_PREDICTED,
    SAMPLE_RESERVOIRS, SAMPLE_TIME, SAMPLE_Z, TIMESCALES, finish_mpl,
    mpl_panels, np, plt,
):
    _t = np.asarray(SAMPLE_TIME)
    _z = np.asarray(SAMPLE_Z)
    _res = np.asarray(SAMPLE_RESERVOIRS).reshape(len(TIMESCALES), -1)
    _colours = plt.get_cmap(MPL_SEQUENTIAL)(np.linspace(0.25, 0.9, len(TIMESCALES)))

    _fig, (_ax0, _ax1) = mpl_panels(
        ncols=2,
        titles=("The same weather, four memories",
                "Hasselmann's amplitude law"),
        figsize=(10.2, 4.0),
    )
    # Each trace divided by its own spread and offset, because the amplitudes
    # differ by a factor of 16 across the hierarchy: on a shared axis the
    # slowest reservoir is a flat line and the *shape* difference -- the point
    # of the panel -- is invisible.
    _offset = 5.0
    _ax0.plot(_t, (_z - _z.mean()) / _z.std() + _offset * len(TIMESCALES),
              "-", color=C_BG, linewidth=0.4, alpha=0.7)
    _ax0.text(_t[-1], _offset * len(TIMESCALES), "  weather $z$", fontsize=8,
              color=C_BG, va="center")
    for _k, _T in enumerate(TIMESCALES):
        _level = _offset * (len(TIMESCALES) - 1 - _k)
        _ax0.axhline(_level, color=C_BG, linestyle=":", linewidth=0.6)
        _ax0.plot(_t, _res[_k] / _res[_k].std() + _level, "-",
                  color=_colours[_k], linewidth=1.4)
        _ax0.text(_t[-1], _level, f"  $T = {_T:g}$", fontsize=8,
                  color=_colours[_k], va="center")
    _ax0.set_xlim(_t[0], _t[-1] * 1.16)
    _ax0.set_yticks([])
    _ax0.set_xlabel("time (TU)")
    _ax0.set_ylabel("each trace scaled by its own spread")

    _T = np.asarray(TIMESCALES)
    _scaled = np.asarray(RESERVOIR_SD) * np.sqrt(_T)
    _ax1.semilogx(_T, _scaled, "o-", color=C_TRUTH, markersize=10,
                  linewidth=2.2, label="measured $\\sigma_S\\sqrt{T}$")
    _ax1.axhline(_scaled[-1], color=C_BG, linestyle="--", linewidth=1.5)
    _ax1.text(_T[0], _scaled[-1] * 1.03,
              "the law: constant", fontsize=8, color=C_BG)
    _ax1.set_xlabel("reservoir memory $T$")
    _ax1.set_ylabel("$\\sigma_S\\sqrt{T}$")
    _ax1.set_xticks(_T)
    _ax1.set_xticklabels([f"{t:g}" for t in _T])
    _ax1.legend(fontsize=8, framealpha=0.9)
    finish_mpl(_fig, "Memory is a parameter; amplitude is a consequence")
    return


@app.cell(hide_code=True)
def s1_note(
    RESERVOIR_SD, RESERVOIR_SD_PREDICTED, RESERVOIR_SD_RATIO, SIGMA_Z,
    TAU_INT, TIMESCALES, mo, np,
):
    _sd = np.asarray(RESERVOIR_SD)
    _ratio = np.asarray(RESERVOIR_SD_RATIO)
    mo.md(
        rf"""
    **The slower the reservoir, the smaller its fluctuations** — $\sigma_S$ falls from
    {_sd[0]:.3f} to {_sd[-1]:.4f} across the hierarchy, very nearly as $1/\sqrt T$. That
    is the trade-off at the heart of Earth system prediction: a component with a long
    memory has a lot of *predictability* and very little *amplitude*, and one with a
    short memory has the reverse.

    **And the law is only asymptotic.** With $\sigma_z = {SIGMA_Z:.2f}$ and an integral
    timescale for the weather of just ${TAU_INT:.5f}$ time units, the predicted
    amplitudes are exceeded by factors of
    {", ".join(f"{r:.2f}" for r in _ratio)} at
    $T = {", ".join(f"{t:g}" for t in TIMESCALES)}$ — converging towards 1 as the
    reservoir slows, and 2.2 times too small for the fastest.

    The reason is the approximation, not the model. Hasselmann's result needs the driving
    to look *white* on the reservoir's own timescale. Lorenz 63's $z$ decorrelates in a
    couple of tenths of a time unit and has a strongly negative autocorrelation lobe
    after that — which is why its integral timescale is so small — but "a couple of
    tenths" is not negligible against $T = 2$. So the fastest reservoir carries a direct,
    un-integrated response to the weather on top of its Hasselmann part.

    That is not a detail to be tidied away. It is the reason a lag-1 autocorrelation
    fitted to the fastest reservoir returns a memory **three times too short**, and the
    reason the next section measures memory from *forecasts* instead.
    """
    )
    return


# ===========================================================================
# Section 2
# ===========================================================================
@app.cell(hide_code=True)
def s2_md(ANALYSIS_FRACTION, CASES, SKILL_THRESHOLD, mo):
    mo.md(
        rf"""
    ## 2 · What initialising buys, and for exactly how long

    {CASES} forecast cases, each run twice from the same weather analysis. One has its
    reservoirs **initialised** (with an analysis error of
    {100 * ANALYSIS_FRACTION:.0f} % of each reservoir's climatological spread); the other
    draws them from **climatology**. Everything else is identical, so the difference is
    the value of initialising.

    The algebra is worth doing first, because it turns out to be exact. Write the
    reservoir as Ornstein–Uhlenbeck with memory $T$ and climatological spread $\sigma$.
    An initialised forecast and the truth share their predictable part up to the analysis
    error $\epsilon$, and their unpredictable parts are **independent**:

    $$
    \operatorname{{var}}\varepsilon_{{\rm init}}(\ell)
      = \epsilon^2 e^{{-2\ell/T}} + 2\sigma^2\!\left(1 - e^{{-2\ell/T}}\right),
    \qquad
    \operatorname{{var}}\varepsilon_{{\rm uninit}} = 2\sigma^2 .
    $$

    (The saturation is $2\sigma^2$, not $\sigma^2$ — two independent draws from the same
    distribution. Getting that wrong shifts the answer below by a fifth of a memory time,
    which is how it was caught.) So the **advantage** is a pure exponential,

    $$
    \operatorname{{var}}\varepsilon_{{\rm uninit}} - \operatorname{{var}}\varepsilon_{{\rm init}}
      = \left(2\sigma^2 - \epsilon^2\right) e^{{-2\ell/T}},
    $$

    and the lead at which the initialised RMSE reaches
    {100 * SKILL_THRESHOLD:.0f} % of the uninitialised one is

    $$
    \ell^\ast = -\frac{{T}}{{2}}
      \ln \frac{{2\sigma^2\left(1 - f^2\right)}}{{2\sigma^2 - \epsilon^2}} .
    $$

    **Strictly proportional to the memory.** Nothing else can change the scale.
    """
    )
    return


@app.cell(hide_code=True)
def s2_controls(TIMESCALES, mo):
    reservoir_pick = mo.ui.dropdown(
        options={f"T = {t:g}": i for i, t in enumerate(TIMESCALES)},
        value=f"T = {TIMESCALES[2]:g}",
        label="reservoir",
    )
    reservoir_pick
    return (reservoir_pick,)


@app.cell(hide_code=True)
def s2_fig(
    ADVANTAGE, ADVANTAGE_SLOPE, ADVANTAGE_SLOPE_LAW, ANALYSIS_FRACTION,
    CLIM_SD, C_ANALYSIS, C_BG, C_OBS, C_PERT, C_TRUTH, ERROR_INITIALISED,
    ERROR_UNINITIALISED, LEADS, SKILL_THRESHOLD, TIMESCALES, USEFUL_LEAD,
    USEFUL_LEAD_PREDICTED, errorgrowth, finish_mpl, mpl_panels, np,
    reservoir_pick,
):
    _k = int(reservoir_pick.value)
    _T = TIMESCALES[_k]
    _n = len(TIMESCALES)
    _leads = np.asarray(LEADS)
    _ei = np.asarray(ERROR_INITIALISED).reshape(_n, -1)[_k]
    _eu = np.asarray(ERROR_UNINITIALISED).reshape(_n, -1)[_k]
    _adv = np.asarray(ADVANTAGE).reshape(_n, -1)[_k]
    _sd = np.asarray(CLIM_SD)[_k]

    _fig, (_ax0, _ax1) = mpl_panels(
        ncols=2,
        titles=(f"Forecast error, $T = {_T:g}$",
                "The advantage decays at exactly $2/T$"),
        figsize=(10.2, 4.0),
    )
    _ax0.plot(_leads, np.sqrt(_eu) / _sd, "-", color=C_PERT, linewidth=2.4,
              label="uninitialised (climatology)")
    _ax0.plot(_leads, np.sqrt(_ei) / _sd, "-", color=C_ANALYSIS, linewidth=2.4,
              label="initialised")
    # the closed form, drawn live rather than stored
    _theory = np.sqrt(errorgrowth.initialised_error_variance(
        _leads, _T, ANALYSIS_FRACTION * _sd, _sd)) / _sd
    _ax0.plot(_leads, _theory, "--", color=C_TRUTH, linewidth=1.6,
              label="closed form")
    _predicted = errorgrowth.initialised_useful_lead(
        _T, ANALYSIS_FRACTION * _sd, _sd, SKILL_THRESHOLD)
    _ax0.axvline(_predicted, color=C_BG, linestyle=":", linewidth=1.5)
    _ax0.set_xlim(0, min(_leads[-1], 4.0 * _T))
    _ax0.set_xlabel("lead (TU)")
    _ax0.set_ylabel("RMSE / climatological spread")
    _ax0.legend(fontsize=8, framealpha=0.9, loc="lower right")

    _positive = _adv > 0
    _ax1.semilogy(_leads[_positive] / _T, _adv[_positive] / _adv[0], "-",
                  color=C_OBS, linewidth=2.4, label="measured")
    _ax1.semilogy(_leads / _T, np.exp(-2.0 * _leads / _T), "--",
                  color=C_TRUTH, linewidth=1.8, label="$e^{-2\\ell/T}$")
    _ax1.set_xlim(0, 3.0)
    _ax1.set_ylim(1e-3, 2.0)
    _ax1.set_xlabel("lead / $T$")
    _ax1.set_ylabel("advantage, relative to lead zero")
    _ax1.legend(fontsize=8, framealpha=0.9)
    finish_mpl(
        _fig,
        f"useful lead: measured {np.asarray(USEFUL_LEAD)[_k]:.1f} TU, "
        f"predicted {_predicted:.1f} TU",
    )
    return


@app.cell(hide_code=True)
def s2_summary(
    ADVANTAGE_SLOPE, ADVANTAGE_SLOPE_LAW, C_BG, C_OBS, C_TRUTH, TIMESCALES,
    USEFUL_LEAD, USEFUL_LEAD_COEFFICIENT, USEFUL_LEAD_PREDICTED, finish_mpl,
    mpl_panels, np,
):
    _T = np.asarray(TIMESCALES)
    _fig, (_ax0, _ax1) = mpl_panels(
        ncols=2,
        titles=("Decay rate against the law",
                "Useful lead is proportional to memory"),
        figsize=(10.2, 3.8),
    )
    _ax0.semilogx(
        _T, np.asarray(ADVANTAGE_SLOPE) / np.asarray(ADVANTAGE_SLOPE_LAW),
        "o-", color=C_OBS, markersize=10, linewidth=2.2,
    )
    _ax0.axhline(1.0, color=C_BG, linestyle="--", linewidth=1.5)
    _ax0.set_ylim(0.6, 1.4)
    _ax0.set_xlabel("reservoir memory $T$")
    _ax0.set_ylabel("fitted rate / $(2/T)$")
    _ax0.set_xticks(_T)
    _ax0.set_xticklabels([f"{t:g}" for t in _T])

    _ax1.loglog(_T, np.asarray(USEFUL_LEAD), "o", color=C_OBS, markersize=11,
                label="measured")
    _line = np.linspace(_T[0] * 0.7, _T[-1] * 1.4, 40)
    _ax1.loglog(_line, USEFUL_LEAD_COEFFICIENT * _line, "-", color=C_TRUTH,
                linewidth=2.2,
                label=f"${USEFUL_LEAD_COEFFICIENT:.3f}\\,T$, no fitted constant")
    _ax1.set_xlabel("reservoir memory $T$")
    _ax1.set_ylabel("useful lead (TU)")
    _ax1.set_xticks(_T)
    _ax1.set_xticklabels([f"{t:g}" for t in _T])
    _ax1.legend(fontsize=8, framealpha=0.9, loc="upper left")
    finish_mpl(_fig, None)
    return


@app.cell(hide_code=True)
def s2_note(
    ADVANTAGE_SLOPE, ADVANTAGE_SLOPE_LAW, TIMESCALES, USEFUL_LEAD,
    USEFUL_LEAD_COEFFICIENT, USEFUL_LEAD_PREDICTED, mo, np,
):
    _ratio = np.asarray(ADVANTAGE_SLOPE) / np.asarray(ADVANTAGE_SLOPE_LAW)
    _lead_ratio = np.asarray(USEFUL_LEAD) / np.asarray(USEFUL_LEAD_PREDICTED)
    mo.md(
        rf"""
    **The law holds where the reservoir is genuinely slow.** The fitted decay rate over
    the predicted $2/T$ comes out
    {", ".join(f"{r:.2f}" for r in _ratio)} at
    $T = {", ".join(f"{t:g}" for t in TIMESCALES)}$, and the useful lead over its
    prediction {", ".join(f"{r:.2f}" for r in _lead_ratio)}. For the two middle
    reservoirs that is agreement to **4–5 %** on a law with no fitted constant.

    The two departures are the two ends, for two different reasons, and both are
    identifiable rather than mysterious. At $T = {TIMESCALES[0]:g}$ the reservoir is not
    slow enough for the weather to look white — section 1's problem — so it is not an
    Ornstein–Uhlenbeck process and has no business obeying an Ornstein–Uhlenbeck law. At
    $T = {TIMESCALES[-1]:g}$ the control run is only 150 memory times long, so the
    climatological spread it is scored against is itself uncertain by several per cent.
    **Every low-order result of this kind has one of those two problems**, and quoting a
    hierarchy without saying which end is which is the mistake.

    /// admonition | What this says about a real prediction system
        type: note

    The useful lead is ${USEFUL_LEAD_COEFFICIENT:.3f}\,T$, and the coefficient depends on
    the analysis error only **logarithmically** — improving the analysis a hundredfold, from
    30 % of the climatological spread to 0.3 %, moves the coefficient from 1.141 to 1.164.
    A 2 % gain.

    So the memory is everything and the observing system is almost nothing. You cannot buy
    decadal skill in a component whose memory is a season by observing it better; you can
    only find a slower component. That is the honest case for caring about the deep ocean,
    and it is also why the components that offer the longest leads are the ones with the
    smallest signals — section 1's trade-off, arriving as an operational constraint.
    ///
    """
    )
    return


# ===========================================================================
# Section 3
# ===========================================================================
@app.cell(hide_code=True)
def s3_md(mo):
    mo.md(
        r"""
    ## 3 · The forcing is part of the state

    Now the structural change. Emissions $E$ are prescribed; the carbon reservoir they
    fill is drained by a sink whose residence time **lengthens as the climate warms**:

    $$
    \dot C = E - \frac{C}{\tau_0\,(1 + \alpha S_1)} ,
    \qquad \rho_{\rm eff} = \rho_{\rm ref} + \kappa_C C .
    $$

    More carbon raises the forcing, which warms the fast system, which warms $S_1$, which
    weakens the sink, which leaves more carbon. A loop, with gain

    $$
    g = \underbrace{E\tau_0}_{C_0}\;\alpha\,\kappa_C\,\lambda
        \frac{\mathrm{d}\langle z\rangle}{\mathrm{d}\rho} ,
    $$

    and — since the carbon equation is linear in $C$ once $\langle z\rangle$ is
    linearised in $\rho_{\rm eff}$ — an exactly solvable equilibrium,
    $C/C_0 = (1 + \alpha S_1^{\rm base})/(1 - g)$.

    Vary the two parameters and watch the closed form; the measured equilibria are
    plotted against it.
    """
    )
    return


@app.cell(hide_code=True)
def s3_controls(mo):
    alpha_pick = mo.ui.slider(
        start=0.0, stop=0.12, step=0.005, value=0.04,
        label="sink sensitivity $\\alpha$", show_value=True,
    )
    sink_pick = mo.ui.slider(
        start=20.0, stop=90.0, step=5.0, value=50.0,
        label="sink time $\\tau_0$", show_value=True,
    )
    mo.hstack([alpha_pick, sink_pick], justify="start", gap=2)
    return alpha_pick, sink_pick


@app.cell(hide_code=True)
def s3_fig(
    CARBON_FORCING, EMISSIONS, FEEDBACK_AMPLIFICATION,
    FEEDBACK_AMPLIFICATION_PREDICTED, FEEDBACK_GAIN, SATURATION_ALPHAS,
    SATURATION_ASYMPTOTE, SATURATION_TIME, SATURATION_TRACK, SINK_TIME,
    C_BG, C_FIXED, C_OBS, C_PERT, C_TRUTH, alpha_pick, finish_mpl,
    mpl_panels, np, sink_pick, systems,
):
    _alpha, _tau = float(alpha_pick.value), float(sink_pick.value)
    _gain_now = systems.earth_system_loop_gain(
        EMISSIONS, _tau, _alpha, CARBON_FORCING)
    _amp_now = systems.earth_system_amplification(
        EMISSIONS, _tau, _alpha, CARBON_FORCING)

    _fig, (_ax0, _ax1) = mpl_panels(
        ncols=2,
        titles=("Equilibrium amplification against loop gain",
                "Past $g = 1$: saturation, not explosion"),
        figsize=(10.2, 4.0),
    )
    _g = np.linspace(0.0, 0.95, 200)
    _ax0.plot(_g, 1.0 / (1.0 - _g), "-", color=C_TRUTH, linewidth=2.4,
              label="$1/(1-g)$, closed form")
    _ax0.plot(np.asarray(FEEDBACK_GAIN), np.asarray(FEEDBACK_AMPLIFICATION),
              "o", color=C_OBS, markersize=10, label="measured")
    if np.isfinite(_amp_now):
        _ax0.plot([_gain_now], [_amp_now], "*", color=C_FIXED, markersize=20,
                  markeredgecolor=C_BG, label="your setting")
    _ax0.axvline(1.0, color=C_PERT, linestyle=":", linewidth=1.5)
    _ax0.set_ylim(0.8, 8.0)
    _ax0.set_xlim(0.0, 1.05)
    _ax0.set_xlabel("loop gain $g$")
    _ax0.set_ylabel("$C / C_0$")
    _ax0.legend(fontsize=8, framealpha=0.9, loc="upper left")

    _t = np.asarray(SATURATION_TIME)
    _track = np.asarray(SATURATION_TRACK).reshape(len(SATURATION_ALPHAS), -1)
    for _i, _a in enumerate(SATURATION_ALPHAS):
        _gain = systems.earth_system_loop_gain(
            EMISSIONS, SINK_TIME, _a, CARBON_FORCING)
        _ax1.plot(_t, _track[_i], "-", linewidth=2.2,
                  color=[C_OBS, C_PERT][_i % 2], label=f"$g = {_gain:.2f}$")
        _ax1.plot(_t, np.asarray(SATURATION_ASYMPTOTE)[_i] * _t, "--",
                  color=C_BG, linewidth=1.3,
                  label="$E - 1/(\\tau_0\\alpha\\kappa_C)$" if _i == 0 else None)
    _ax1.set_xlabel("time (TU)")
    _ax1.set_ylabel("carbon $C$")
    _ax1.legend(fontsize=8, framealpha=0.9, loc="upper left")
    finish_mpl(
        _fig,
        f"your setting: $g = {_gain_now:.3f}$, "
        + ("amplification " + f"{_amp_now:.2f}" if np.isfinite(_amp_now)
           else "no equilibrium"),
    )
    return


@app.cell(hide_code=True)
def s3_note(
    FEEDBACK_AMPLIFICATION, FEEDBACK_GAIN, FEEDBACK_WORST_ABOVE_HALF,
    FEEDBACK_WORST_BELOW_HALF, FEEDBACK_Z, SATURATION_ASYMPTOTE,
    SATURATION_RATE, mo, np,
):
    _rate = np.asarray(SATURATION_RATE) / np.asarray(SATURATION_ASYMPTOTE)
    mo.md(
        rf"""
    **The closed form is right where it is entitled to be.** For $g \le 0.5$ the measured
    amplification matches $1/(1-g)$ to **{FEEDBACK_WORST_BELOW_HALF} %**. Beyond that it
    degrades, to {FEEDBACK_WORST_ABOVE_HALF} % at $g = 0.80$ — and for an identifiable
    reason rather than a mysterious one. The derivation linearises
    $\langle z\rangle$ in $\rho_{{\rm eff}}$ using $\mathrm{{d}}\langle z\rangle/\mathrm{{d}}\rho
    = 1.0007$, measured over $\rho \in [26, 40]$. At $g = 0.80$ the equilibrium has
    carried $\langle z\rangle$ to {np.asarray(FEEDBACK_Z)[-1]:.0f}, far outside that
    range. **The feedback formula fails first not because the feedback is strong but
    because the climate sensitivity it was built on is no longer the right number.**

    **And past $g = 1$ the word "runaway" is wrong.** The residence time grows linearly
    in $C$, so the sink term $C/[\tau_0(1 + \alpha\kappa_C C)]$ approaches the *constant*
    $1/(\tau_0\alpha\kappa_C)$ and carbon accumulates at the fixed rate
    $E - 1/(\tau_0\alpha\kappa_C)$ for ever. Measured at $t = 12{{,}}000$, the late growth
    rate is {", ".join(f"{r:.2f}" for r in _rate)} of that asymptote and still
    approaching. It is a **saturation** — the sink stops working — not a divergence, and
    the distinction matters because the two have different signatures and different
    remedies.

    A limitation to state plainly: this model has **no permanent airborne fraction**. Cut
    emissions and the sink removes all the carbon, the forcing returns to its unforced
    value, and every reservoir relaxes back. A test asserts exactly that. So nothing here
    speaks to zero-emissions commitment, which is a real and important quantity that
    needs a carbon cycle with an irreversible pathway this model does not have.
    """
    )
    return


# ===========================================================================
# Section 4
# ===========================================================================
@app.cell(hide_code=True)
def s4_md(SPREAD_ALPHAS, SPREAD_EMISSIONS, SPREAD_STARTS, mo):
    mo.md(
        rf"""
    ## 4 · Three sources of spread, not two

    Chapter 25 divided a projection into **forced response** and **internal
    variability**. With the forcing prescribed, that is the whole story. With emissions
    prescribed instead, a third term appears: two models given the same emissions realise
    *different forcings*, because their carbon-climate feedbacks differ.

    So the spread across a projection ensemble decomposes three ways —
    {len(SPREAD_ALPHAS)} feedback strengths $\times$ {len(SPREAD_EMISSIONS)} emissions
    scenarios $\times$ {SPREAD_STARTS} start states, {len(SPREAD_ALPHAS) * len(SPREAD_EMISSIONS) * SPREAD_STARTS}
    members in one call:

    * **internal** — variance across start states, averaged over the other two;
    * **feedback** — variance of the feedback-group means;
    * **scenario** — variance of the scenario-group means.

    The interesting result is that the answer depends on **which reservoir you ask
    about**.
    """
    )
    return


@app.cell(hide_code=True)
def s4_fig(
    C_ANALYSIS, C_BG, C_OBS, C_PERT, SPREAD_CROSSOVER, SPREAD_FEEDBACK,
    SPREAD_INTERNAL, SPREAD_SCENARIO, SPREAD_TIME, TIMESCALES, finish_mpl,
    mpl_panels, np,
):
    _n = len(TIMESCALES)
    _t = np.asarray(SPREAD_TIME)
    _int = np.asarray(SPREAD_INTERNAL).reshape(_n, -1)
    _fb = np.asarray(SPREAD_FEEDBACK).reshape(_n, -1)
    _sc = np.asarray(SPREAD_SCENARIO).reshape(_n, -1)
    _show = (0, _n - 1)
    _fig, _axes = mpl_panels(
        ncols=2,
        titles=tuple(f"$T = {TIMESCALES[k]:g}$" for k in _show),
        figsize=(10.2, 4.0),
    )
    for _ax, _k in zip(_axes, _show):
        _total = _int[_k] + _fb[_k] + _sc[_k]
        _shares = [_int[_k] / _total, _fb[_k] / _total, _sc[_k] / _total]
        _ax.stackplot(
            _t, *_shares,
            colors=[C_ANALYSIS, C_PERT, C_OBS], alpha=0.85,
        )
        _ax.axhline(0.5, color=C_BG, linestyle="--", linewidth=1.2)
        _ax.set_xlim(_t[1], _t[-1])
        _ax.set_ylim(0.0, 1.0)
        _ax.set_xlabel("lead (TU)")
        _ax.set_ylabel("share of total variance")
    for _label, _y, _colour in (
        ("internal variability", 0.06, "#08343d"),
        ("carbon feedback", 0.40, "#4a0b1c"),
        ("emissions scenario", 0.88, "#4a2400"),
    ):
        _axes[0].text(_t[-1] * 0.97, _y, _label, fontsize=8.5, ha="right",
                      color=_colour, fontweight="bold")
    finish_mpl(
        _fig,
        "Which uncertainty dominates depends on which component you ask about",
    )
    return


@app.cell(hide_code=True)
def s4_note(
    SPREAD_CROSSOVER, SPREAD_INTERNAL_SHARE_END, SPREAD_TIME, TIMESCALES,
    mo, np,
):
    _share = np.asarray(SPREAD_INTERNAL_SHARE_END)
    _cross = np.asarray(SPREAD_CROSSOVER)
    _end = np.asarray(SPREAD_TIME)[-1]
    mo.md(
        rf"""
    | reservoir | internal share at lead {_end:.0f} | internal share falls below half at |
    |---|---|---|
    {"".join(
        f"| $T = {t:g}$ | {100*s:.2f} % | {c:.0f} TU |" + chr(10)
        for t, s, c in zip(TIMESCALES, _share, _cross)
    )}

    **For the fastest reservoir internal variability never stops mattering** — it is
    still **{100*_share[0]:.1f} %** of the total spread at the longest lead. For the
    slowest it is **{100*_share[-1]:.2f} %**, which is to say gone. The same ensemble,
    the same forcing, the same everything: only the question changed.

    That is the practical content of the hierarchy. A projection of a fast component is a
    statement about a *distribution*, permanently, exactly as chapter 25 found — no amount
    of narrowing the parameters helps, because most of the spread is not parametric. A
    projection of a slow component is a statement about a *number*, and its uncertainty is
    almost entirely the scenario you chose and the feedback you assumed. **Those need
    completely different research programmes**, and conflating them is how a genuine
    disagreement about parameters gets mistaken for irreducible noise, or the reverse.

    Note also which term is *not* here: initialisation. Section 2's advantage decays on
    ${1.141:.3g}\,T$, so by the leads this figure covers it has gone for every reservoir
    but the slowest. Initialisation and scenario uncertainty live at different leads and
    barely interact — which is why decadal prediction and climate projection are
    separate enterprises, as chapters 24 and 25 found from the other direction.
    """
    )
    return


# ===========================================================================
# Section 5
# ===========================================================================
@app.cell(hide_code=True)
def s5_md(WINDOW_HI, WINDOW_LO, mo):
    mo.md(
        rf"""
    ## 5 · An emergent constraint, measured exactly, that tells you nothing

    Section 4 leaves an obvious question. If the feedback strength $\alpha$ contributes a
    quarter of the spread at long lead, and $\alpha$ is not directly observable, can it
    be *inferred* from something that is?

    That is the logic of an **emergent constraint**: find a present-day observable that
    correlates with the future response across a model ensemble, measure it in the real
    world, and read off the constrained response. Here the natural observable is exactly
    the real one — the sensitivity of the **carbon growth rate** to climate variability
    *[citation needed: Cox et al. (2013)]*. Differentiating the carbon equation gives its
    expectation in closed form:

    $$
    \frac{{\partial \dot C}}{{\partial S_1}}
      = \frac{{C\,\alpha}}{{\tau_0\,(1 + \alpha S_1)^2}} .
    $$

    Measured on the window $[{WINDOW_LO:g}, {WINDOW_HI:g}]$ of each member, on detrended
    anomalies.
    """
    )
    return


@app.cell(hide_code=True)
def s5_fig(
    C_ANALYSIS, C_BG, C_FIXED, C_OBS, C_PERT, C_TRUTH, DEGENERATE_OBSERVABLE,
    DEGENERATE_RESPONSE, ONE_EXPECTED, ONE_OBSERVABLE, ONE_PARAMETER_ALPHAS,
    ONE_RESPONSE, R_ONE, R_TWO, TWO_OBSERVABLE, TWO_RESPONSE, finish_mpl,
    mpl_panels, np,
):
    _a = np.asarray(ONE_PARAMETER_ALPHAS)
    _obs = np.asarray(ONE_OBSERVABLE)
    _exp = np.asarray(ONE_EXPECTED)
    _fig, (_ax0, _ax1) = mpl_panels(
        ncols=2,
        titles=("The observable is exactly what theory says",
                "And it does not constrain the response"),
        figsize=(10.2, 4.0),
    )
    _ax0.plot(_a, _exp, "-", color=C_TRUTH, linewidth=2.4,
              label="$C\\alpha/[\\tau_0(1+\\alpha S_1)^2]$, exact")
    _ax0.plot(_a, _obs, "o", color=C_OBS, markersize=9, label="measured")
    _ax0.set_xlabel("sink sensitivity $\\alpha$")
    _ax0.set_ylabel("observable")
    _ax0.legend(fontsize=8, framealpha=0.9, loc="lower right")
    _peak = int(np.argmax(_exp))
    _ax0.axvline(_a[_peak], color=C_PERT, linestyle=":", linewidth=1.5)
    _ax0.text(_a[_peak], _exp.min() + 0.35 * (_exp.max() - _exp.min()),
              " it turns over here", fontsize=8.5, color=C_PERT, va="bottom")

    _ax1.plot(_obs, np.asarray(ONE_RESPONSE), "o", color=C_ANALYSIS,
              markersize=9, label=f"one parameter, $r = {R_ONE:+.2f}$")
    _ax1.plot(np.asarray(TWO_OBSERVABLE), np.asarray(TWO_RESPONSE), "s",
              color=C_PERT, markersize=8,
              label=f"two parameters, $r = {R_TWO:+.2f}$")
    _dob = np.asarray(DEGENERATE_OBSERVABLE)
    _dre = np.asarray(DEGENERATE_RESPONSE)
    _ax1.plot(_dob, _dre, "*", color=C_FIXED, markersize=22,
              markeredgecolor=C_BG, linestyle="-", linewidth=2.0,
              label="observationally identical")
    _ax1.set_xlabel("observable")
    _ax1.set_ylabel("long-term response (equilibrium $C$)")
    _ax1.set_ylim(0.0, 1.45 * max(np.asarray(ONE_RESPONSE).max(),
                                  np.asarray(TWO_RESPONSE).max()))
    _ax1.legend(fontsize=7.5, framealpha=0.95, loc="upper right")
    finish_mpl(_fig, "A good measurement of the wrong quantity")
    return


@app.cell(hide_code=True)
def s5_note(
    CLAIMED_REDUCTION, DEGENERATE_ALPHA, DEGENERATE_OBSERVABLE_GAP,
    DEGENERATE_RESPONSE, DEGENERATE_RESPONSE_GAP, DEGENERATE_SINK,
    ONE_CORRELATION, ONE_PEAK_ALPHA, ONE_WORST_DEPARTURE, R_AMPLIFICATION,
    R_ONE, R_TWO, TRANSIENT_BEST_RATIO, TRANSIENT_WINDOW,
    TRANSIENT_WRONG_SIGN_COUNT, mo, np,
):
    _corr = np.asarray(ONE_CORRELATION)
    _dre = np.asarray(DEGENERATE_RESPONSE)
    _dal = np.asarray(DEGENERATE_ALPHA)
    _dsi = np.asarray(DEGENERATE_SINK)
    mo.md(
        rf"""
    **The measurement is excellent.** Across the ensemble the observable matches its exact
    expectation to **{ONE_WORST_DEPARTURE} %** at worst, with a within-record correlation
    between climate anomaly and carbon growth rate of
    {_corr.min():.2f}–{_corr.max():.2f}. If the question were "can this be measured", the
    answer is an emphatic yes.

    **It constrains nothing.** Across the one-parameter ensemble the correlation between
    observable and response is only **${R_ONE:+.2f}$**, and the standard constraint
    calculation — regression, prediction interval, observational error — reports a
    narrowing of **{CLAIMED_REDUCTION} %**. The arithmetic is not lying to us; there is
    simply no information in the predictor.

    The cause is in the formula. The observable goes as $C\alpha/(1+\alpha S_1)^2$ and
    $S_1$ grows faster than linearly in $\alpha$, so the denominator eventually wins:
    the observable **turns over at $\alpha \approx {ONE_PEAK_ALPHA}$** while the response
    keeps accelerating. A non-monotone predictor cannot be inverted, however precisely it
    is measured.

    **With a second parameter it is worse than uninformative.** Letting the sink time
    $\tau_0$ vary as well — every member still with a genuine equilibrium — the
    correlation with the response becomes **${R_TWO:+.2f}$**, the *wrong sign*, and the
    correlation with the amplification factor $1/(1-g)$, which is the quantity the
    constraint nominally targets, is **${R_AMPLIFICATION:+.3f}$**. Zero.

    The concrete version is the starred pair:

    | | $\alpha$ | $\tau_0$ | observable | response |
    |---|---|---|---|---|
    | A | {_dal[0]:.3f} | {_dsi[0]:.0f} | \- | {_dre[0]:.2f} |
    | B | {_dal[1]:.3f} | {_dsi[1]:.0f} | {DEGENERATE_OBSERVABLE_GAP} % from A | {_dre[1]:.2f} |

    Two models **{DEGENERATE_OBSERVABLE_GAP} % apart** in the observable and
    **{DEGENERATE_RESPONSE_GAP} % apart** in the response — a factor of
    {_dre[1] / _dre[0]:.1f}. No amount of observational precision separates them, because
    the observable is a function of $C$, $\tau_0$ *and* $\alpha$ jointly, and the response
    depends on a different combination of the same three.

    /// admonition | And a measurement trap on top of the physics one
        type: warning

    Everything above uses **detrended** anomalies. Measured on a transient window
    $[{TRANSIENT_WINDOW[0]:g}, {TRANSIENT_WINDOW[1]:g}]$ instead — a growing carbon
    reservoir, which is the situation of any real record — the undetrended observable has
    the **wrong sign for every member of the ensemble**, because a rising $C$ means a
    falling $\dot C$ while $S_1$ rises, and the regression measures that trend rather than
    the sensitivity. Removing a straight line is not enough either: the transient is
    curved, so even detrended the estimate recovers at most {TRANSIENT_BEST_RATIO} of the
    exact value and still has the wrong sign for
    {TRANSIENT_WRONG_SIGN_COUNT:.0f} of 17 members.

    So the honest ordering of difficulties is: get the trend removal right, *then* discover
    that the quantity you have carefully measured does not answer the question.
    ///
    """
    )
    return


# ===========================================================================
# Section 6
# ===========================================================================
@app.cell(hide_code=True)
def s6_md(mo):
    mo.md(
        r"""
    ## 6 · What to take away

    **Memory is a parameter; amplitude is a consequence.** Reservoirs differing only in
    $T$ have spreads falling as $1/\sqrt{T}$ — so a long-memory component offers a lot of
    predictability and very little signal, and a short-memory one the reverse. Hasselmann's
    amplitude law is approached from above as $T$ grows and is a factor of 2.2 out for the
    fastest reservoir, because the weather is not white on a timescale of 2.

    **The useful lead of an initialised forecast is $1.141\,T$, and essentially nothing
    else.** The advantage decays as $e^{-2\ell/T}$ exactly; the coefficient depends on the
    analysis error logarithmically, so a hundredfold better analysis buys 2 %. Measured to
    4–5 % for the reservoirs that are genuinely slow, with identified failures at both
    ends. **You cannot observe your way to decadal skill in a seasonal component.**

    **When the forcing is a state variable, its feedback has an exactly solvable gain.**
    $C/C_0 = 1/(1-g)$ to 0.7 % for $g \le 0.5$, failing at large $g$ not because the
    feedback is strong but because the climate sensitivity the derivation used is no longer
    the right number. Past $g = 1$ the sink **saturates** — carbon accumulates at a fixed
    rate for ever — which is a different phenomenon from a runaway.

    **A projection has three uncertainties, and their ranking depends on the question.**
    Internal variability is 10.9 % of the spread for the fastest reservoir even at the
    longest lead, and 0.05 % for the slowest. Fast components need a distributional
    answer permanently; slow components need better parameters and a chosen scenario.

    **An emergent constraint can be a perfect measurement of the wrong quantity.** The
    observable here matches its closed form to 5.7 % with a within-record correlation of
    0.99, and correlates with the response at $+0.37$ in one parameter, $-0.44$ in two,
    and $-0.005$ with the feedback factor itself. Two models 1.6 % apart in the observable
    differ by a factor of 6.3 in response. **The failure is not statistical and cannot be
    fixed with more data**: the observable is not a monotone function of the physics, and
    the standard constraint calculation reports the resulting narrowing as −1 % if you
    look at the prediction interval rather than the regression line.

    ### What this model cannot do

    Worth stating, because a low-order model invites over-reading. There is **no permanent
    airborne fraction** — cut emissions and all the carbon leaves, so nothing here speaks
    to zero-emissions commitment. The reservoirs are **passive**, for the reason chapter 24
    measured. There is no cryosphere, no vegetation, no ocean circulation, and $\rho$ is
    not a greenhouse gas. What transfers is the *structure*: a hierarchy of memories, a
    forcing that is part of the state, and a three-way uncertainty budget.

    ### Try this

    1. Section 2's useful lead is $1.141\,T$. Work out what analysis error would be needed
       to double it, and say whether that number is physically meaningful.
    2. The amplification formula fails at $g = 0.8$ because $\langle z\rangle$ has left the
       range where $\mathrm{d}\langle z\rangle/\mathrm{d}\rho$ was fitted. Design a
       measurement that would fix it, and say what it costs.
    3. Section 4's ranking inverts between the fastest and slowest reservoirs. At what
       memory do the two terms cross, and what sets that timescale?
    4. The emergent constraint fails because the observable turns over. Propose a second
       observable that would break the degeneracy, and state what it must be sensitive to.

    ### Where this goes next

    **Chapter 27** takes the case where the response is not smooth at all — a forcing that
    destroys the state the system is in — and asks whether *that* can be seen coming.
    **Chapter 28** asks whether predictability itself has changed, which is this chapter's
    hierarchy with its parameters in motion.

    ### Further reading

    - Hasselmann (1976), stochastic climate models *[citation needed]*
    - Cox et al. (2013), on constraining the carbon-climate feedback from interannual
      variability *[citation needed]*
    - Hawkins & Sutton (2009), on the sources of uncertainty in climate projections
      *[citation needed]*
    - Friedlingstein et al., on carbon-cycle feedback intercomparison *[citation needed]*
    - Hall et al. (2019), on the promise and pitfalls of emergent constraints
      *[citation needed]*
    - Boer et al., on the Decadal Climate Prediction Project protocol *[citation needed]*
    """
    )
    return


if __name__ == "__main__":
    app.run()
